function radixEmpezarAyuntamiento() {
    G.capital = 6871;
    G.reputation = 78;
    G.bar = 98;
    G.turn = 10;
    refreshDash();
    radixActualizarCodigoUI();
    initSimulation();
}

function initSimulation() {
    G.simulationStarted = true;
    G.simScreen = 'week';
    G.simMonth = 1;
    G.simWeek = 1;
    G.weekQuestions = buildWeeklyQuestions();
    G.pnlHistory = [];
    G.weekDecisionHistory = [];
    G.currentPnL = createEmptyPnL();
    showWeek();
    radixAutoGuardarAhora();
}

function shuffleArray(arr) {
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--) {
        var j = Math.floor(Math.random() * (i + 1));
        var tmp = a[i]; a[i] = a[j]; a[j] = tmp;
    }
    return a;
}

