function applyPnLDelta(categoria, dinero) {
    if (!dinero) return;
    var revenueFields = { ingresos_operativos: 1, ingresos_financieros: 1, subvenciones: 1 };
    var fieldMap = {
        'ninguna': null,
        'ingresos_operativos': 'ingresos_operativos',
        'ingresos_financieros': 'ingresos_financieros',
        'operativos (ventas)': 'ingresos_operativos',
        'ingresos operativos': 'ingresos_operativos',
        'ventas': 'ingresos_operativos',
        'ingresos financieros': 'ingresos_financieros',
        'financieros': 'ingresos_financieros',
        'subvenciones': 'subvenciones',
        'compras/materiales': 'compras',
        'compras': 'compras',
        'materiales': 'compras',
        'servicios': 'servicios',
        'impuestos': 'impuestos',
        'suministros': 'suministros',
        'asesoria': 'asesoria',
        'publicidad': 'publicidad',
        'marketing': 'publicidad',
        'personal': 'personal',
        'nominas': 'personal',
        'alquiler': 'alquiler',
        'seguros': 'seguros',
        'otros_gastos': 'otros_gastos',
        'otros gastos': 'otros_gastos',
        'otros': 'otros_gastos',
        'costos_financieros': 'costos_financieros',
        'costos financieros': 'costos_financieros',
        'coste financiero': 'costos_financieros',
        'prestamo': 'costos_financieros'
    };
    var norm = (categoria || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
    var field = fieldMap.hasOwnProperty(norm) ? fieldMap[norm] : 'otros_gastos';
    if (field === null) return;
    if (revenueFields[field]) {
        G.currentPnL[field] += dinero;
    } else {
        G.currentPnL[field] = Math.max(0, G.currentPnL[field] - dinero);
    }
}

function createEmptyPnL() {
    return {
        ingresos_operativos: G.monthlyRevenue,
        ingresos_financieros: 0,
        subvenciones: 0,
        compras: G.variableCosts.supplies || 0,
        servicios: (G.variableCosts.transport || 0) + (G.variableCosts.commissions || 0) + (G.variableCosts.misc || 0) + (G.fixedCosts.telecom || 0),
        impuestos: 0,
        suministros: G.variableCosts.utilities || 0,
        asesoria: G.fixedCosts.advisory || 0,
        publicidad: G.fixedCosts.ads || G.marketingBudget || 0,
        personal: (G.ssCost || 0) + (G.fixedCosts.wages || 0) + (G.fixedCosts.ssEmployees || 0),
        alquiler: G.fixedCosts.rent || 0,
        seguros: G.fixedCosts.insurance || 0,
        otros_gastos: 0,
        costos_financieros: G.fixedCosts.loan || 0
    };
}

function makeMonthBar(currentMonth, currentWeek) {
  var pct = Math.round(((currentMonth - 1) * 4 + (currentWeek - 1)) / 48 * 100);
  var h = '<div data-radix-estilo="r120">';
  h += '<div data-radix-estilo="r121">';
  h += '<span data-radix-estilo="r122">Progreso de simulación</span>';
  h += '<span data-radix-estilo="r123">Mes '+currentMonth+'/12</span>';
  h += '</div>';
  h += '<div data-radix-estilo="r124">';
  h += '<div data-radix-estilo="r125" data-radix-dinamico="'+radixEstiloDinamico([(pct)+'%'])+'"></div>';
  h += '</div>';
  h += '<div data-radix-estilo="r126">';
  for(var m=1;m<=12;m++){
    var done = m < currentMonth || (m === currentMonth && currentWeek > 1);
    var active = m === currentMonth;
    var col = active ? 'var(--acc)' : done ? 'var(--suc)' : 'var(--muted)';
    var fw = active ? '800' : done ? '600' : '400';
    h += '<span data-radix-estilo="r127" data-radix-dinamico="'+radixEstiloDinamico([col,fw])+'">'+m+'</span>';
  }
  h += '</div></div>';
  return h;
}

function radixProgresoSemana(){
    if(!G.weekProgress || G.weekProgress.month!==G.simMonth || G.weekProgress.week!==G.simWeek){
        G.weekProgress={month:G.simMonth,week:G.simWeek,opened:false,selected:'',resolved:false,feedbackHtml:''};
    }
    return G.weekProgress;
}

function radixRestaurarSemana(){
    var progreso=radixProgresoSemana();
    if(progreso.opened && G.currentQuestion){
        RADIX_RESTORING_WEEK=true;
        try{
            if(G.currentQuestion.formato==='correo') abrirCorreo();
            else if(G.currentQuestion.formato==='whatsapp') abrirWhatsapp();
            else if(G.currentQuestion.formato==='noticia') abrirNoticia();
        }finally{RADIX_RESTORING_WEEK=false;}
    }
    var opciones=el('weekEv');
    if(opciones && progreso.selected!==''){
        opciones.setAttribute('data-picked',String(progreso.selected));
        var todas=opciones.querySelectorAll('.op');
        for(var i=0;i<todas.length;i++){
            if(todas[i].getAttribute('data-v')===String(progreso.selected)) todas[i].classList.add('sel');
            else todas[i].classList.remove('sel');
        }
    }
    if(progreso.legacyUncertain){
        if(el('simFb')) el('simFb').innerHTML=
          '<div class="al al-w"><span class="ai">⚠️</span>Esta semana se guardó con una versión anterior. ¿Ya habías pulsado Resolver? Así evitamos aplicar dos veces el mismo resultado.</div>'+ 
          '<div class="bc"><button class="btn bs" data-radix-click="accion37">Sí, ya la resolví</button>'+ 
          '<button class="btn bp" data-radix-click="accion38">No, aún no</button></div>';
        if(el('resolverBox')) radixFijarEstilo(el('resolverBox'),'display','none');
        return;
    }
    if(progreso.resolved){
        if(el('simFb')) el('simFb').innerHTML=progreso.feedbackHtml||'';
        if(el('resolverBox')) radixFijarEstilo(el('resolverBox'),'display','none');
        if(opciones) radixFijarEstilo(opciones,'pointer-events','none');
    }
}

function radixConfirmarSemanaAnterior(yaResuelta){
    var progreso=radixProgresoSemana();
    if(!progreso.legacyUncertain) return;
    progreso.legacyUncertain=false;
    if(yaResuelta){
        progreso.resolved=true;
        var pregunta=G.currentQuestion;
        var indice=Number(progreso.selected);
        var impacto=pregunta && pregunta.impactos && pregunta.impactos[indice];
        if(impacto){
            if(!Array.isArray(G.weekDecisionHistory)) G.weekDecisionHistory=[];
            if(!G.weekDecisionHistory.some(function(item){return item.month===G.simMonth && item.week===G.simWeek;})){
                var movimientos=impacto.movimientos||[{dinero:impacto.dinero,categoria_pnl:impacto.categoria_pnl}];
                var dinero=movimientos.reduce(function(total,item){return total+(Number(item.dinero)||0);},0);
                G.weekDecisionHistory.push({month:G.simMonth,week:G.simWeek,
                    question:pregunta.pregunta||pregunta.asunto||pregunta.formato||'',
                    choice:indice,answer:pregunta.opciones[indice],money:dinero,
                    reputation:impacto.reputacion||0,movements:movimientos});
            }
        }
        progreso.feedbackHtml='<div class="al al-i"><span class="ai">✓</span>Se ha conservado el resultado que ya estaba guardado para esta semana.</div>'+ 
          '<div class="bc" data-radix-estilo="r128"><button class="btn bp" data-radix-click="accion39">Continuar →</button></div>';
    }
    showWeek();
}

