function abrirCorreo(){

    var q = G.currentQuestion;

    var inicial = q.remitente.charAt(0).toUpperCase();

    var html =
    '<div class="mail">'+

        '<div class="mailHeader">'+

            '<div class="mailAvatar">'+inicial+'</div>'+

            '<div class="mailTitle">'+
                '<h3>'+q.remitente+'</h3>'+
                '<span>Notificación oficial</span>'+
            '</div>'+

        '</div>'+

        '<div class="mailInfo">'+
            '<div><strong>De:</strong> '+q.email+'</div>'+
            '<div><strong>Para:</strong> '+q.destinatario+'</div>'+
            '<div><strong>Fecha:</strong> '+q.fecha+'</div>'+
            '<div><strong>Asunto:</strong> '+q.asunto+'</div>'+
        '</div>'+

        '<div class="mailBody">'+
            q.mensaje+
            '<div class="mailFirma">'+q.firma+'</div>'+
        '</div>';

    if(q.adjunto){
        html +=
        '<div class="mailAdjunto">📎 '+q.adjunto+'</div>';
    }

    html +=
        '<p data-radix-estilo="r142"><strong>¿Qué decides?</strong></p>';

    var icons = ['1️⃣','2️⃣','3️⃣'];
    var opts = [];

    for(var i=0;i<q.opciones.length;i++){
        opts.push({
            v:i,
            ic:icons[i] || '🔹',
            t:q.opciones[i],
            d:''
        });
    }

    html += makeOpts('weekEv', opts, 'c3', true);

    html += '</div>';

    document.getElementById("mailPreview").innerHTML = html;


    // Mostrar botón Resolver después de leer el correo
    var resolver = document.getElementById("resolverBox");
    if(resolver){
        radixFijarEstilo(resolver,'display','flex');
    }
    if(!RADIX_RESTORING_WEEK){radixProgresoSemana().opened=true;radixProgramarAutoGuardado();}
}

